import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export interface Job {
  id: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL,
      steps INTEGER NOT NULL, fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL,
      progress_completed INTEGER NOT NULL, result TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
      idempotency_key TEXT UNIQUE, payload TEXT NOT NULL, available_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_status_order ON jobs(status, created_at);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK(id=1), at INTEGER NOT NULL);
  `);
  return db;
}

type JobRow = {
  id: string; status: Job['status']; input: string; steps: number; fail_attempts: number;
  attempts: number; progress_completed: number; result: string | null; error: string | null;
  created_at: string; updated_at: string;
};

export function toJob(row: JobRow): Job {
  return {
    id: row.id, status: row.status, input: row.input, steps: row.steps,
    failAttempts: row.fail_attempts, attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.result === null ? null : JSON.parse(row.result) as { output: string },
    error: row.error, createdAt: row.created_at, updatedAt: row.updated_at,
  };
}

