import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type Job } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: { field: string; message: string }[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
function jobById(id: string): Job | undefined {
  const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id);
  return row ? toJob(row as never) : undefined;
}
async function bodyJson(req: IncomingMessage): Promise<{ value?: unknown; malformed?: boolean }> {
  try {
    let data = '';
    for await (const chunk of req) {
      data += chunk.toString();
      if (data.length > 100_000) return { malformed: true };
    }
    return { value: JSON.parse(data) as unknown };
  } catch { return { malformed: true }; }
}
type Payload = { input: string; steps: number; failAttempts: number };
function validate(value: unknown): { payload?: Payload; fields: { field: string; message: string }[] } {
  const fields: { field: string; message: string }[] = [];
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return { fields: [{ field: 'body', message: 'must be a JSON object' }] };
  const obj = value as Record<string, unknown>;
  for (const key of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'is not allowed' });
  if (!Object.hasOwn(obj, 'input')) fields.push({ field: 'input', message: 'is required' });
  else if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'must be a string' });
  else if (obj.input.length < 1 || obj.input.length > 1000 || obj.input.trim().length === 0) fields.push({ field: 'input', message: 'must be 1–1000 characters and not only whitespace' });
  const steps = Object.hasOwn(obj, 'steps') ? obj.steps : 5;
  const failAttempts = Object.hasOwn(obj, 'failAttempts') ? obj.failAttempts : 0;
  if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
  if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
  if (fields.length) return { fields };
  return { payload: { input: obj.input as string, steps: steps as number, failAttempts: failAttempts as number }, fields };
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const beat = db.prepare('SELECT at FROM worker_heartbeat WHERE id=1').get() as { at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: beat && Date.now() - beat.at <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/' ) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all();
      return send(res, 200, { jobs: rows.map(row => toJob(row as never)) });
    }
    if (req.method !== 'POST') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const contentType = req.headers['content-type'] ?? '';
    const fields: { field: string; message: string }[] = [];
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    const key = req.headers['idempotency-key'];
    if (key !== undefined && (Array.isArray(key) || !/^[A-Za-z0-9_-]{1,128}$/.test(key))) fields.push({ field: 'Idempotency-Key', message: 'must contain 1–128 letters, digits, underscores, or hyphens' });
    const idempotencyKey = typeof key === 'string' ? key : undefined;
    const parsed = await bodyJson(req);
    if (parsed.malformed) fields.push({ field: 'body', message: 'must contain valid JSON' });
    const validated = parsed.malformed ? undefined : validate(parsed.value);
    if (validated) fields.push(...validated.fields);
    if (fields.length || !validated?.payload) return error(res, 400, 'invalid_request', 'Request is invalid.', fields);
    const payload = validated.payload;
    const payloadJson = JSON.stringify(payload);
    if (idempotencyKey !== undefined) {
      const prior = db.prepare('SELECT * FROM jobs WHERE idempotency_key=?').get(idempotencyKey) as (Record<string, unknown> & { payload: string }) | undefined;
      if (prior) {
        if (prior.payload !== payloadJson) return error(res, 409, 'idempotency_conflict', 'The idempotency key was already used with a different request.');
        return send(res, 200, toJob(prior as never));
      }
    }
    const now = new Date().toISOString(), id = randomUUID();
    try {
      db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,result,error,created_at,updated_at,idempotency_key,payload)
        VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, ?)`)
        .run(id, payload.input, payload.steps, payload.failAttempts, now, now, idempotencyKey ?? null, payloadJson);
    } catch (e) {
      // The unique idempotency constraint protects simultaneous submissions from racing.
      if (idempotencyKey !== undefined) {
        const prior = db.prepare('SELECT * FROM jobs WHERE idempotency_key=?').get(idempotencyKey) as (Record<string, unknown> & { payload: string }) | undefined;
        if (prior) return prior.payload === payloadJson ? send(res, 200, toJob(prior as never)) : error(res, 409, 'idempotency_conflict', 'The idempotency key was already used with a different request.');
      }
      throw e;
    }
    return send(res, 201, jobById(id));
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string;
    try { id = decodeURIComponent(match[1]!); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const job = jobById(id);
    return job ? send(res, 200, job) : error(res, 404, 'not_found', 'Job not found.');
  }
  error(res, 404, 'not_found', 'Route not found.');
});
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => {
  server.close(() => { db.close(); process.exit(0); });
});

