import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running record has no live owner after a worker restart. Attempts are retained so
// the retry limit applies across process crashes as well as simulated failures.
const recoveryTime = new Date().toISOString();
db.prepare("UPDATE jobs SET status='failed', error='transient failure', result=NULL, updated_at=? WHERE status='running' AND attempts>=3")
  .run(recoveryTime);
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, available_at=0, updated_at=? WHERE status='running' AND attempts<3")
  .run(recoveryTime);
const heartbeat = () => db.prepare('INSERT INTO worker_heartbeat(id,at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET at=excluded.at').run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(() => { try { heartbeat(); } catch {} }, 1000);

interface Task { id: string; input: string; steps: number; fail_attempts: number; attempts: number; }
function claim(): Task | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT id,input,steps,fail_attempts,attempts FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(Date.now()) as Task | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const now = new Date().toISOString();
    db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'").run(now, row.id);
    db.exec('COMMIT');
    return { ...row, attempts: row.attempts + 1 };
  } catch (e) { db.exec('ROLLBACK'); throw e; }
}

function fail(task: Task): void {
  const now = new Date().toISOString();
  if (task.attempts >= 3) {
    db.prepare("UPDATE jobs SET status='failed', error='transient failure', result=NULL, updated_at=? WHERE id=? AND status='running'").run(now, task.id);
  } else {
    db.prepare("UPDATE jobs SET status='queued', progress_completed=0, available_at=?, updated_at=? WHERE id=? AND status='running'")
      .run(Date.now() + 500, now, task.id);
  }
}

console.log('worker started');
try {
  while (!stopping) {
    const task = claim();
    if (!task) { await sleep(100); continue; }
    if (task.attempts <= task.fail_attempts) { fail(task); continue; }
    let interrupted = false;
    for (let step = 1; step <= task.steps; step++) {
      await sleep(100);
      if (stopping) { interrupted = true; break; }
      const now = new Date().toISOString();
      db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(step, now, task.id);
    }
    if (interrupted) break;
    const now = new Date().toISOString();
    db.prepare("UPDATE jobs SET status='completed', progress_completed=steps, result=?, error=NULL, updated_at=? WHERE id=? AND status='running'")
      .run(JSON.stringify({ output: task.input.toUpperCase() }), now, task.id);
  }
} finally {
  clearInterval(heartbeatTimer);
  db.close();
}

