28	    const list = document.querySelector('[data-testid="job-list"]');
29	    const form = document.querySelector('[data-testid="job-form"]');
30	    const errorRegion = document.querySelector('[data-testid="form-error"]');
31	    const make = (tag, testid, value) => { const node = document.createElement(tag); node.dataset.testid = testid; node.textContent = value; return node; };
32	    function render(jobs) {
33	      list.replaceChildren(...jobs.map(job => {
34	        const item = document.createElement('li'); item.className = 'job'; item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
35	        const name = document.createElement('strong'); name.textContent = job.input; item.append(name);
36	        const status = make('p', 'job-status', job.status);
37	        const progress = make('p', 'job-progress', `${job.progress.completed}/${job.progress.total}`);
38	        const result = make('p', 'job-result', job.result ? job.result.output : (job.error || ''));
39	        item.append(status, progress, result); return item;
40	      }));
